const allVideos = ($json.value || []).filter(f => /\.(mp4|mkv|webm|mov|avi)$/i.test(f.name));
const MIN_SIZE = 1024 * 1024; // 1MB - abaixo disso, quase certamente ainda sincronizando com o OneDrive

// Nao encontrar video (fila vazia) ou encontrar so videos ainda sincronizando NAO sao erros de verdade -
// sao estados esperados, especialmente com o Schedule Trigger rodando a cada 6h mesmo sem nada novo na fila.
// Por isso retornamos um item normal com videoFound:false + mensagem, em vez de lancar throw new Error(...)
// (que marcava a execucao inteira como "error" no historico do n8n). O node "Video Encontrado?" logo depois
// decide se segue o pipeline (true) ou para por ali (false), sem gerar nenhum erro.
if (allVideos.length === 0) {
  return [{ json: { videoFound: false, message: 'Nenhum video encontrado na pasta Videos-Cortes no momento - fila vazia, nada a processar.' } }];
}

const ready = allVideos.filter(f => (f.size || 0) > MIN_SIZE);
if (ready.length === 0) {
  const pending = allVideos.map(f => f.name + ' (' + (f.size || 0) + ' bytes)').join(', ');
  return [{ json: { videoFound: false, message: 'O(s) video(s) encontrado(s) na pasta ainda parece(m) estar sincronizando com o OneDrive (tamanho 0 ou muito pequeno): ' + pending + '. O desktop client do OneDrive pode levar minutos (ou mais, para arquivos grandes de culto ao vivo) para terminar o upload. Aguarde a sincronizacao completar e rode o workflow novamente (ou aguarde a proxima checagem agendada).' } }];
}

return [{ json: { videoFound: true, ...ready[0] } }];

const out = $json.stdout || '';
if (out.includes('STATUS:LOCKED')) {
  const lockContentMatch = out.match(/LOCK_CONTENT:(.+)/);
  const ageMatch = out.match(/LOCK_AGE_SECONDS:(\d+)/);
  const lockContent = lockContentMatch ? lockContentMatch[1].trim() : 'desconhecido|desconhecido';
  const [lockedVideo, lockedAt] = lockContent.split('|');
  const ageSeconds = ageMatch ? parseInt(ageMatch[1]) : 0;
  const ageHours = (ageSeconds / 3600).toFixed(1);
  // Colisao de trava e um estado esperado (Schedule Trigger a cada 6h + self-chaining podem se sobrepor
  // quando o processamento de um video leva mais de 6h) - nao e um erro de verdade, entao nao lancamos
  // throw new Error(...) aqui (isso marcava a execucao inteira como "error" no historico do n8n, mesmo
  // sendo um resultado seguro). Retornamos lockAcquired:false + mensagem; o node "Trava Liberada?" logo
  // depois decide se segue (true) ou para por ali sem erro (false) - mesmo padrao do "Video Encontrado?".
  return [{ json: { lockAcquired: false, lockMessage: 'Ja existe outra execucao em andamento processando o video "' + (lockedVideo || 'desconhecido') + '" (iniciada em ' + (lockedAt || '?') + ', ha ' + ageHours + 'h). Esta execucao foi interrompida automaticamente para evitar rodar 2 transcricoes whisper.cpp simultaneas na mesma VPS - o servidor tem so 6 nucleos e o whisper.cpp ja usa todos eles (-t 6) por execucao, entao rodar 2 ao mesmo tempo deixa as duas extremamente lentas (ou travadas) em vez de mais rapidas. Aguarde a execucao em andamento terminar (tipicamente ~5h para um video de ~2h de culto) - o self-chaining ou a proxima checagem agendada vao tentar de novo automaticamente. Se a execucao anterior travou ou falhou sem limpar a trava, ela expira sozinha apos 8h; ou apague manualmente o arquivo /home/node/.n8n-files/.processing.lock na VPS para liberar antes disso.' } }];
}
return [{ json: { ...$('Selecionar Vídeo').first().json, lockAcquired: true } }];

const t = $('Selecionar Vídeo').first().json;
const base = '/home/node/.n8n-files/';
return [{ json: { videoName: t.name, videoPath: base + t.name, audioPath: base + 'audio_full.wav' }}];

const c = $('Preparar Caminhos').first().json;
const out = $json.stdout || '';
const m = out.match(/DURATION:([\d.]+)/);
const duration = m ? parseFloat(m[1]) : 0;
// Threshold de silencio calibrado por video em vez de -30dB fixo: o piso de ruido ambiente varia muito
// entre gravacoes (mic de igreja, room tone), de -13dB a -25dB em amostras reais - um threshold fixo
// mais rigoroso que isso faz o silencedetect nunca disparar, deixando a extensao por silencio do fim
// (e o novo snap do inicio) silenciosamente inoperantes. Ver CLAUDE.md, auditoria do agente clipador
// (29/07/2026) - a mesma calibracao ja usada na validacao foi trazida para o pipeline de producao.
const mv = out.match(/MEANVOL:(-?[\d.]+)/);
const meanVolume = mv ? parseFloat(mv[1]) : -20;
let noiseThreshold = meanVolume - 12;
if (noiseThreshold > -18) noiseThreshold = -18;
if (noiseThreshold < -40) noiseThreshold = -40;
const srtBase = '/home/node/.n8n-files/transcript_full';
return [{ json: { ...c, duration, noiseThreshold, srtBase, srtPath: srtBase + '.srt' } }];

const raw = $json.stdout || '';
const blocks = raw.split(/\n\n+/).map(b => {
  const ls = b.trim().split('\n');
  const tl = ls.find(l => l.includes(' --> '));
  if (!tl) return null;
  const tm = tl.match(/(\d+):(\d+):(\d+),(\d+) --> (\d+):(\d+):(\d+),(\d+)/);
  if (!tm) return null;
  const s = +tm[1]*3600 + +tm[2]*60 + +tm[3] + +tm[4]/1000;
  const e = +tm[5]*3600 + +tm[6]*60 + +tm[7] + +tm[8]/1000;
  const txt = ls.filter(l => !l.match(/^\d+$/) && !l.includes(' --> ')).join(' ').trim();
  return { s, e, txt };
}).filter(Boolean);
const GAP_MIN = 0.5;
const merged = [];
for (const b of blocks) {
  const last = merged[merged.length - 1];
  if (last && (b.s - last.e) < GAP_MIN) {
    last.e = b.e;
    last.txt = (last.txt + ' ' + b.txt).trim();
  } else {
    merged.push({ s: b.s, e: b.e, txt: b.txt });
  }
}
function fmt(t) {
  const h = Math.floor(t/3600), m = Math.floor((t%3600)/60), s = Math.floor(t%60), ms = Math.round((t - Math.floor(t)) * 1000);
  const pad = (n, l) => String(n).padStart(l||2, '0');
  return pad(h)+':'+pad(m)+':'+pad(s)+','+pad(ms,3);
}
const mergedSrt = merged.map((b, i) => (i+1)+'\n'+fmt(b.s)+' --> '+fmt(b.e)+'\n'+b.txt).join('\n\n');
return [{ json: { ...$json, stdout: mergedSrt, srtOriginalSegCount: blocks.length, srtMergedSegCount: merged.length } }];

const srt = $json.stdout || '';
const c = $('Preparar Whisper Blocos').first().json;
const BLOCK = 180;
const segs = srt.split(/\n\n+/).map(b => {
  const ls = b.trim().split('\n');
  const tl = ls.find(l => l.includes(' --> '));
  if (!tl) return null;
  const tm = tl.match(/(\d+):(\d+):(\d+),(\d+) --> (\d+):(\d+):(\d+),(\d+)/);
  if (!tm) return null;
  const s = +tm[1]*3600 + +tm[2]*60 + +tm[3] + +tm[4]/1000;
  const e = +tm[5]*3600 + +tm[6]*60 + +tm[7] + +tm[8]/1000;
  const txt = ls.filter(l => !l.match(/^\d+$/) && !l.includes(' --> ')).join(' ');
  return { s, e, txt };
}).filter(Boolean);
const blocks = []; let bs = 0, cur = [];
for (let i = 0; i < segs.length; i++) {
  const seg = segs[i]; cur.push(seg);
  if (seg.e - bs >= BLOCK || i === segs.length - 1) {
    blocks.push({ blockIndex: blocks.length+1, start: Math.round(bs), end: Math.round(seg.e), text: cur.map(x=>x.txt).join(' ') });
    bs = seg.e; cur = [];
  }
}
return [{ json: { ...c, srtContent: srt, blocks: JSON.stringify(blocks), blockCount: blocks.length } }];

const raw = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '').trim();
const match = raw.match(/\[[\s\S]*\]/);
if (!match) throw new Error('IA nao retornou JSON de blocos. Resposta: ' + raw.slice(0, 300));
let scores; try { scores = JSON.parse(match[0]); } catch(e) { throw new Error('JSON invalido: ' + e.message); }
if (!Array.isArray(scores)) scores = scores.blocks || scores.scores || [];
// Seguranca de codigo: forca score=0 para qualquer bloco cuja fase (campo reportado pela IA) nao seja pregacao,
// independente do numero que a IA tenha escrito - nao confia so no teto numerico de 5 sugerido no prompt.
scores = scores.map(s => (s.fase && s.fase !== 'pregacao') ? { ...s, score: 0 } : s);
scores.sort((a,b) => b.score - a.score);
const MIN_SCORE = 40;
let qualified = scores.filter(s => s.score >= MIN_SCORE);
let usedFallback = false;
let fallbackReason = null;

if (qualified.length === 0) {
  // FALLBACK: em vez de travar o pipeline inteiro quando nenhum bloco atinge a nota minima, usa os blocos
  // de fase=pregacao (mesmo com nota baixa) como guia para a 2a IA, em vez de abortar a execucao.
  // A 2a IA ("Selecao Final") recebe a transcricao COMPLETA de qualquer forma, nao so o resumo dos blocos
  // aprovados - entao um bloco-score pessimista da 1a IA nao precisa impedir a analise fina do proximo passo.
  // Isso e mais robusto do que continuar ajustando o prompt de scoring: 3 execucoes reais consecutivas
  // (com prompts diferentes) travaram exatamente aqui para o mesmo video, sugerindo que a 1a IA e
  // sistematicamente pessimista demais para sermoes de fala muito continua/repetitiva - mas isso nao
  // significa que nao ha NENHUM recorte aproveitavel no video inteiro.
  const pregacaoBlocks = scores.filter(s => s.fase === 'pregacao');
  if (pregacaoBlocks.length === 0) {
    const faseCounts = {};
    scores.forEach(s => { const f = s.fase || 'desconhecida'; faseCounts[f] = (faseCounts[f]||0) + 1; });
    const faseBreakdown = Object.entries(faseCounts).map(([f,n]) => f+':'+n).join(', ');
    throw new Error('Nenhum bloco foi classificado como fase=pregacao pela IA - o video inteiro (ou a parte transcrita) pode ser abertura/avisos/dizimo/louvor, ou a IA classificou incorretamente. Distribuicao de fases: ' + faseBreakdown + '. Notas: ' + scores.map(s=>s.blockIndex+':'+s.score+'('+(s.fase||'?')+')').join(', '));
  }
  usedFallback = true;
  fallbackReason = 'Nenhum bloco atingiu a nota minima de ' + MIN_SCORE + ' (maior nota entre os ' + pregacaoBlocks.length + ' blocos de pregacao: ' + Math.max(...pregacaoBlocks.map(s=>s.score)) + '). Prosseguindo mesmo assim com os blocos de pregacao disponiveis como guia - a selecao fina fica a cargo da 2a IA, que le a transcricao completa.';
  qualified = pregacaoBlocks;
}

const allBlocks = JSON.parse($('Dividir em Blocos').first().json.blocks || '[]');
const topN = usedFallback ? 8 : 5;
const scoredBlocks = qualified.slice(0, topN).map(s => {
  const b = allBlocks.find(x => x.blockIndex === s.blockIndex) || {};
  return { blockIndex: s.blockIndex, score: s.score, reason: s.reason, criteria: s.criteria || null, start: b.start, end: b.end };
});
const topBlocksFull = allBlocks.filter(b => scoredBlocks.find(s => s.blockIndex === b.blockIndex));
const c = $('Preparar Whisper Blocos').first().json;
// Quando usedFallback, os blocos vieram de um teto de qualidade que nenhum atingiu - anexar a nota
// numerica ali (ex: "nota: 5/100") sinaliza contraditoriamente "pior" logo abaixo do titulo "melhores
// blocos", o que pode deixar a 2a IA mais conservadora do que deveria na selecao final (ver CLAUDE.md).
const summary = topBlocksFull.map(b => {
  const sb = scoredBlocks.find(s => s.blockIndex === b.blockIndex) || {};
  const label = usedFallback
    ? '=== Bloco ' + b.blockIndex + ' [' + b.start + 's-' + b.end + 's] (candidato - sem nota confiavel) ==='
    : '=== Bloco ' + b.blockIndex + ' [' + b.start + 's-' + b.end + 's] (nota: ' + sb.score + '/100) ===';
  return label + '\n' + b.text;
}).join('\n\n');
return [{ json: { ...c, srtContent: $('Dividir em Blocos').first().json.srtContent, topBlocksSummary: summary, scoredBlocks, blockScoringFallback: usedFallback, blockScoringFallbackReason: fallbackReason } }];

const sys = "Você é um editor sênior de YouTube Shorts especialista em retenção de audiência em português. Com base nos melhores blocos e a transcrição SRT completa, selecione de 5 a 8 clipes finais avaliando 7 critérios. IMPORTANTE: os blocos que você recebeu já passaram por um filtro que descarta abertura do culto, avisos, apelo de dízimo/oferta, louvor e encerramento do culto — mas se, mesmo assim, algum trecho da transcrição SRT completa pertencer a uma dessas fases (isso pode acontecer nas bordas de um bloco, no início ou no fim, ou no final da transcrição), NUNCA selecione um clipe dali. Todo clipe final deve vir exclusivamente da pregação/mensagem principal ("a palavra") — nunca de abertura/boas-vindas, avisos/recados, apelo de dízimos e ofertas, louvor/música, ou encerramento do culto (oração final, bênção, despedida).

1. GANCHO INICIAL (obrigatório): Clipe começa com frase que prende nos 3s? Sem gancho = descartado.
2. EMOÇÃO NA FALA: Priorize linguagem emocional — surpresa, entusiasmo, indignação, empatia.
3. VELOCIDADE DA FALA: Use timestamps SRT para calcular ritmo (palavras/segundo). Ideal 2-3 p/s.
4. MUDANÇA DE TOM: Prefira trechos com variação de energia (pergunta→resposta, problema→solução, exclamações).
5. PALAVRAS DE IMPACTO: Favoreça trechos com: segredo, erro, nunca, sempre, incrível, revelação, cuidado, atenção, simples, impossível.
6. DURAÇÃO IDEAL: 40-70s preferencialmente. Mínimo 45s. TETO ABSOLUTO E INEGOCIÁVEL: 180 segundos (3 minutos — limite técnico do YouTube Shorts e do pipeline; qualquer clipe acima disso é descartado automaticamente pelo código, mesmo que você o retorne). Se o raciocínio não couber em 70s, avance o 'end' até completar o pensamento, MAS NUNCA passe de 180s totais. Se o pensamento completo precisar de mais de 180s, NÃO tente abarcar tudo: escolha o melhor ponto de conclusão intermediário (uma pausa real de fala que também feche uma ideia, mesmo que não seja o fechamento perfeito do argumento inteiro) que fique DENTRO do teto de 180s a partir do start. NUNCA trunque no meio de uma frase ou palavra, e NUNCA retorne um clipe com mais de 180s.
7. RETENÇÃO ESTIMADA: O clipe cria tensão/curiosidade suficiente para ser assistido até o fim?

⚠️ FORMATO DE TIMESTAMP OBRIGATÓRIO: todos os valores de 't', 'start' e 'end' devem ser em SEGUNDOS TOTAIS (número decimal). Converta o formato SRT HH:MM:SS,mmm assim: segundos = H×3600 + M×60 + S + mmm/1000. Exemplos: 00:01:08,400 → 68.4 | 00:37:28,000 → 2248.0 | 00:02:04,100 → 124.1. NUNCA use o formato MM.SS como decimal — 02:04 NÃO é 2.04, é 124 segundos.

PASSO 1 — PONTOS DE CONCLUSÃO: Você vai receber um CHECKLIST OBRIGATÓRIO DE COBERTURA no início da mensagem do usuário, com janelas de tempo do vídeo — siga-o à risca, é mais importante que a ordem de leitura natural do texto. Leia TODA a transcrição, do início ao fim, e identifique 15–25 momentos onde o pregador conclui um pensamento completo (responde uma pergunta, fecha uma ilustração, resume um ponto, resolve um argumento). IMPORTANTE: como pregadores costumam falar em arcos longos, procure ATIVAMENTE por pontos de conclusão intermediários dentro de cada raciocínio longo (a cada 40-180s), não só no fechamento final do argumento inteiro — isso garante que sempre exista uma opção de 'end' dentro do teto de 180s no PASSO 2. Os pontos DEVEM estar espalhados por TODA a duração informada, cobrindo CADA janela do checklist com pelo menos 2 pontos — se você notar que todos os seus pontos estão concentrados numa janela pequena do início, PARE, releia o restante da transcrição SRT completa (fornecida no final da mensagem) e adicione pontos das partes posteriores antes de prosseguir. Liste cada um com timestamp (em SEGUNDOS TOTAIS) e resumo de 5 palavras.
ATENÇÃO: a transcrição NÃO tem pontuação (gerada por whisper.cpp) e JÁ FOI PRÉ-PROCESSADA — um passo anterior mesclou automaticamente pausas de respiração (gap < 0.5s) nos blocos SRT antes deste texto chegar até você. Isso significa que TODA quebra de bloco SRT que você vê aqui já representa uma pausa real de fala (≥0.5s) — você NÃO precisa calcular gaps manualmente, eles já foram filtrados. Mas isso NÃO é suficiente sozinho: uma pausa real também pode acontecer no meio de uma enumeração, antes de uma vírgula falada ou entre uma conjunção — nesses casos a quebra de bloco SRT é uma pausa real, mas NÃO é uma conclusão de pensamento. Use o fim de um bloco SRT como candidato a 'end' SOMENTE quando o conteúdo também fechar o raciocínio. Sinais adicionais de conclusão: (1) palavras-sinal como "então", "portanto", "por isso", "fica aqui", "entende", "lembra disso", "ou seja"; (2) mudança clara de assunto; (3) afirmação com tom definitivo que encerra o argumento. NÃO marque como conclusão o fim de um bloco que esteja no meio de enumeração ou lista, mesmo que a pausa seja real.

PASSO 2 — SELEÇÃO DE CLIPES (de 5 a 8, seja generoso): Para cada clipe: (a) escolha 'start' com gancho forte nos primeiros 3s; (b) o 'end' DEVE ser um dos pontos de conclusão do PASSO 1 que caia ENTRE start+40s E start+180s (nunca antes, nunca depois — 180s é o teto absoluto, sem exceções) — sempre o timestamp de FIM de um bloco SRT (pausa real já garantida pelo pré-processamento); (c) se nenhum ponto de conclusão estiver nessa janela de start+40s a start+180s, avance o 'start' ou escolha outro trecho — NUNCA escolha um 'end' acima de start+180s só para fechar o raciocínio perfeitamente; (d) o 'start' de cada clipe deve ser ao menos 10s DEPOIS do 'end' do clipe anterior — NUNCA contíguo; (e) os clipes finais DEVEM vir de pelo menos 4 janelas diferentes do checklist de cobertura — não concentre todos os clipes nas primeiras janelas do vídeo. Prefira retornar 8 clipes. Lembre: 'start' e 'end' em SEGUNDOS TOTAIS (ex: start=124.1, end=248.5), e (end - start) NUNCA maior que 180.

REGRAS INEGOCIÁVEIS:
- NENHUM clipe pode vir de abertura do culto, boas-vindas, avisos/recados, apelo de dízimo e oferta, louvor/música, ou encerramento do culto (oração final, bênção, despedida) — somente da pregação/mensagem principal. Isso vale mesmo para os últimos pontos de conclusão do PASSO 1, perto do fim do vídeo — não assuma que estão automaticamente na pregação. Se um ponto de conclusão do PASSO 1 estiver dentro de um desses trechos, descarte-o e não o use como 'end' nem como 'start'.
- 'end' obrigatoriamente em ponto de conclusão real. NUNCA em enumeração, vírgula ou conjunção.
- DURAÇÃO DE CADA CLIPE (end - start) NUNCA PODE ULTRAPASSAR 180 SEGUNDOS. Este é um limite técnico rígido (YouTube Shorts + pipeline), não uma sugestão. Um clipe de 181s ou mais será descartado inteiro pelo sistema. Se um raciocínio precisar de mais tempo, escolha um ponto de conclusão intermediário real dentro do teto, em vez de tentar capturar o argumento inteiro.
- Cortes em pausas de fala, nunca no meio de uma palavra.
- Clipe autocontido: quem assiste sem contexto entende início, meio e fim.
- Clipes NÃO se sobrepõem e NÃO são contíguos: 'start' de cada clipe deve ser ≥10s após o 'end' do anterior (gap mínimo obrigatório de 10s).
- O CHECKLIST DE COBERTURA de janelas de tempo (fornecido no início da mensagem do usuário) é obrigatório: cada janela precisa de pelo menos 2 pontos de conclusão no PASSO 1, e os clipes finais devem vir de pelo menos 4 janelas diferentes.

Retorne APENAS JSON sem markdown:
{"conclusions":[{"t":68.9,"summary":"resumo"}],"clips":[{"start":12.4,"end":68.9,"title":"slug-curto","hook":"Frase exata de abertura","reason":"Por que funciona","retention_score":87}]}";
const _dur = $json.duration || 0;
