const bucketSize = _dur / N_BUCKETS;
let bucketList = '';
for (let i = 0; i < N_BUCKETS; i++) {
  const bStart = Math.round(i * bucketSize);
  const bEnd = Math.round((i + 1) * bucketSize);
  bucketList += (i+1) + '. ' + bStart + 's–' + bEnd + 's — pelo menos 2 pontos de conclusão aqui
';
}
// Quando o "Ranking dos Blocos" caiu no fallback (nenhum bloco atingiu a nota minima), avisa a 2a IA
// explicitamente para nao se ancorar nisso - sem este aviso, a 2a IA tende a ser mais conservadora na
