try { parsed = JSON.parse(raw); } catch(_) { const m = raw.match(/\{[\s\S]*\}/) || raw.match(/\[[\s\S]*\]/); if (!m) throw new Error('IA nao retornou JSON de clipes. Resposta: ' + raw.slice(0, 300)); try { parsed = JSON.parse(m[0]); } catch(e) { throw new Error('JSON invalido: ' + e.message); } }
let clips = (() => { if (Array.isArray(parsed)) return parsed; const c = parsed.clips||parsed.clipes||parsed.cortes; if (c) return c; const a = Object.values(parsed).filter(v=>Array.isArray(v)&&v.length>0&&v[0]&&v[0].start!=null); return a[a.length-1]||[]; })().slice(0, 8);
