  results.push({ clipStart:Math.max(0,clip.start), clipEnd:clip.end, idx, titleSlug:slug, hook:clip.hook||'', reason:clip.reason||'', videoPath:vp, videoName:vn, outPath, audioPath, metaPath, metaContent, noiseThreshold });
